  const world = new World({ seed: 91 });
  const actor = world.create();
  world.add(actor, Position, { x: 5, y: 5 });

  const bowId = world.create();
  world.add(bowId, ItemInfo, { type: "equip", subtype: "bow", range: 8, count: 1 });
